package org.sleepwell.app;

import java.time.*;import java.util.*;

/** Describes observed records only. Missing dates, unavailable goals and absent inputs stay unknown. */
final class RecordInsights {
    static final List<Integer> WINDOWS=List.of(7,30,90);
    static final class Day {final LocalDate date;final Long duration,balance;final Double startMinute;Day(LocalDate date,Long duration,Long balance,Double startMinute){this.date=date;this.duration=duration;this.balance=balance;this.startMinute=startMinute;}}
    static final class Association {final String tag;final int with,without;final long difference;Association(String tag,TagImpact impact){this.tag=tag;with=impact.tagged.count;without=impact.other.count;difference=impact.tagged.mean-impact.other.mean;}}
    final RecordTrends.Range range;final List<Day> days;final List<Association> associations;final int observed,missing,mainPeriods,manual,imported,phone,interrupted,excluded,insufficientTags;final Long average,median,minimum,maximum;final Double startRange;final DatedGoalBank.Summary goal;final boolean goalsAvailable;final long latestRecord;
    RecordInsights(List<RecordEntry> input,List<GoalCommitment> goals,LocalDate end,int window,int cutoff,Instant now){
        if(!WINDOWS.contains(window)||cutoff<0||cutoff>=1440||end.getYear()<2000||end.getYear()>2100)throw new IllegalArgumentException("Invalid insight range");range=new RecordTrends.Range(end.minusDays(window-1),end);List<RecordEntry> eligible=new ArrayList<>();int skipped=0;for(RecordEntry record:input){if(record.rawEnd<=0||record.edit.start<=0||record.edit.end<=record.edit.start||record.edit.end>now.toEpochMilli()||record.edit.end-record.edit.start>36*3600000L){skipped++;continue;}eligible.add(record);}
        SortedMap<LocalDate,RecordTrends.Day> coverage=RecordTrends.days(eligible,range,cutoff);coverage.entrySet().removeIf(e->e.getValue().duration()==0&&e.getValue().entries.stream().anyMatch(r->r.duration()>0));List<Long> durations=new ArrayList<>();for(RecordTrends.Day day:coverage.values())durations.add(day.duration());Collections.sort(durations);observed=durations.size();missing=window-observed;average=observed==0?null:RecordTrends.average(coverage.values());median=observed==0?null:observed%2==1?durations.get(observed/2):(durations.get(observed/2-1)+durations.get(observed/2))/2;minimum=observed==0?null:durations.get(0);maximum=observed==0?null:durations.get(observed-1);
        List<RecordEntry> selected=new ArrayList<>();int m=0,i=0,p=0,interruptions=0;RecordEntry latest=null;for(RecordEntry r:eligible)if(range.contains(r.day(cutoff))){selected.add(r);if(!r.healthConnect.isEmpty())i++;else if(r.manual())m++;else p++;if(r.interrupted!=0)interruptions++;if(latest==null||r.edit.start>latest.edit.start)latest=r;}manual=m;imported=i;phone=p;interrupted=interruptions;excluded=skipped;latestRecord=latest==null?0:latest.id;
        Map<LocalDate,Double> starts=new HashMap<>();for(RhythmStats.Night night:new RhythmStats(eligible,cutoff,31,now.toEpochMilli()).nights)if(range.contains(night.day))starts.put(night.day,night.bedtime);mainPeriods=starts.size();startRange=mainPeriods<2?null:RhythmStats.arc(new ArrayList<>(starts.values()))[1];
        goalsAvailable=goals!=null;DatedGoalBank bank=goalsAvailable?new DatedGoalBank(goals,eligible,now):null;goal=bank==null?new DatedGoalBank.Summary():bank.summary(range);Map<LocalDate,Long> balances=new HashMap<>();if(bank!=null)for(GoalCommitment commitment:goals)if(commitment.metric.equals("duration"))for(GoalProgress.Day day:bank.progress.get(commitment.id).days)if(range.contains(day.date)&&day.balance!=null)balances.merge(day.date,day.balance,Math::addExact);
        List<Day> timeline=new ArrayList<>();for(LocalDate date=range.start;!date.isAfter(range.end);date=date.plusDays(1)){RecordTrends.Day day=coverage.get(date);timeline.add(new Day(date,day==null?null:day.duration(),balances.get(date),starts.get(date)));}days=List.copyOf(timeline);
        List<RecordEntry> mainRecords=new ArrayList<>();for(RecordEntry r:selected)if(r.duration()>=RhythmStats.MAIN_MINIMUM)mainRecords.add(r);List<Association> comparisons=new ArrayList<>();int tooSmall=0;int checked=0;for(String tag:TagImpact.names(mainRecords)){if(checked++>=24||comparisons.size()>=4)break;if(tag.equalsIgnoreCase("nap"))continue;TagImpact impact=new TagImpact(mainRecords,tag,now.toEpochMilli());if(impact.tagged.count<3||impact.other.count<3){tooSmall++;continue;}comparisons.add(new Association(tag,impact));}associations=List.copyOf(comparisons);insufficientTags=tooSmall;
    }
}
